'use strict';

var index = require('./index-OWCBTetj.js');

const cardImageCss = () => `:host{display:block;width:100%;height:100%}.card-image{width:100%;height:100%;object-fit:cover;display:block}.card-image.object-fit-contain{object-fit:contain}.card-image.object-fit-fill{object-fit:fill}.card-image.object-fit-none{object-fit:none}.card-image.object-fit-scale-down{object-fit:scale-down}`;

const CardImage = class {
    constructor(hostRef) {
        index.registerInstance(this, hostRef);
        this.imgPosition = index.createEvent(this, "imgPosition", 7);
    }
    /** Image source URL. */
    src;
    /** Text description of the image for screen readers. */
    alt;
    /** Image position. */
    position;
    /** CSS object-fit value applied to the image. */
    objectFit = "cover";
    /** Emits the image position when it changes or is set. */
    imgPosition;
    handlePosition(position) {
        this.imgPosition.emit(position);
    }
    componentWillLoad() {
        this.handlePosition(this.position);
    }
    componentDidUpdate() {
        this.handlePosition(this.position);
    }
    render() {
        return index.h("img", { key: '1371d2a78317c5df25b3d7f78fb98c8d9b411284', src: this.src, alt: this.alt, class: `card-image ${this.objectFit !== 'cover' ? `object-fit-${this.objectFit}` : ''}` });
    }
};
CardImage.style = cardImageCss();

exports.ifx_card_image = CardImage;
